# children bounding
def worldbb(r):
    pts=[]
    for ch in r.children:
        if ch.type=='MESH':
            for c in ch.bound_box:
                pts.append(ch.matrix_world @ mathutils.Vector(c))
    xs=[p.x for p in pts]; ys=[p.y for p in pts]; zs=[p.z for p in pts]
    return (min(xs),max(xs)),(min(ys),max(ys)),(min(zs),max(zs))
